    [int]$TimeoutSec = 120
)
$ErrorActionPreference = 'Stop'
$ServerIP = '127.0.0.1'
$ServerPort = 60491

$client = New-Object System.Net.Sockets.TcpClient
$client.Connect($ServerIP, $ServerPort)
$stream = $client.GetStream()
$script:closed = $false

# ---- banner (line-based; LF-terminated, 5s cap) ----
$bannerSb = New-Object System.Text.StringBuilder
$oneBuf = New-Object byte[] 1
$bannerDeadline = [DateTime]::UtcNow.AddSeconds(5)
while ([DateTime]::UtcNow -lt $bannerDeadline) {
    if ($stream.DataAvailable) {
        $n = $stream.Read($oneBuf, 0, 1)
        if ($n -le 0) { break }
        if ($oneBuf[0] -eq 10) { break }
        [void]$bannerSb.Append([char]$oneBuf[0])
    } else {
        Start-Sleep -Milliseconds 15
    }
}
$banner = $bannerSb.ToString()
[Console]::Error.WriteLine("BANNER: $banner")
if ($banner -notmatch 'WELCOME UNITY-TCP' -or $banner -notmatch 'FRAMING=1') {
    throw "Unexpected bridge banner: '$banner'"
}

function Write-Frame([string]$payload) {
    $bytes = [System.Text.Encoding]::UTF8.GetBytes($payload)
    $lenBytes = [BitConverter]::GetBytes([UInt64]$bytes.Length)
    [Array]::Reverse($lenBytes)
    $stream.Write($lenBytes, 0, 8)
    $stream.Write($bytes, 0, $bytes.Length)
    $stream.Flush()
}

function Read-Frame([int]$MaxWaitSec) {
    $deadline = [DateTime]::UtcNow.AddSeconds($MaxWaitSec)
    $lenBytes = New-Object byte[] 8
    $off = 0
    while ($off -lt 8) {
        try {
            $n = $stream.Read($lenBytes, $off, 8 - $off)
            if ($n -le 0) { $script:closed = $true; throw 'BRIDGE_CLOSED' }
            $off += $n
        } catch {
            if ($script:closed -or (-not $client.Connected)) { throw }
            if ([DateTime]::UtcNow -ge $deadline) { throw 'BRIDGE_TIMEOUT' }
        }
    }
    [Array]::Reverse($lenBytes)
    $len = [BitConverter]::ToUInt64($lenBytes, 0)
    if ($len -eq 0) { return Read-Frame $MaxWaitSec }
    if ($len -gt 67108864) { throw "Invalid frame length: $len" }
    $payload = New-Object byte[] ([int]$len)
    $off = 0
    while ($off -lt [int]$len) {
        try {
            $n = $stream.Read($payload, $off, [int]$len - $off)
            if ($n -le 0) { $script:closed = $true; throw 'BRIDGE_CLOSED' }
            $off += $n
        } catch {
            if ($script:closed -or (-not $client.Connected)) { throw }
            if ([DateTime]::UtcNow -ge $deadline) { throw 'BRIDGE_TIMEOUT' }
        }
    }
    return [System.Text.Encoding]::UTF8.GetString($payload)
}

# ---- handshake ----
Write-Frame 'CLIENT_VERSION=2'
Write-Frame 'PLATFORM=cli'

# ---- send command ----
$cmdRaw = [System.IO.File]::ReadAllText($CommandJsonPath)
$cmd = $cmdRaw | ConvertFrom-Json
$reqId = [string]$cmd.request_id
Write-Frame $cmdRaw
[Console]::Error.WriteLine("SENT type=$($cmd.type) request_id=$reqId bytes=$($cmdRaw.Length)")

# ---- await matching response ----
$overallDeadline = [DateTime]::UtcNow.AddSeconds($TimeoutSec)
while ($true) {
    $remaining = [int]($overallDeadline - [DateTime]::UtcNow).TotalSeconds
    if ($remaining -le 0) { throw "BRIDGE_TIMEOUT: no response for request_id=$reqId within $TimeoutSec s" }
    $frame = Read-Frame $remaining
    try { $obj = $frame | ConvertFrom-Json } catch {
        [Console]::Error.WriteLine("NON_JSON_FRAME: " + $frame.Substring(0, [Math]::Min(300, $frame.Length)))
        continue
    }
    $props = @($obj.PSObject.Properties.Name)
    if ($props -contains 'notification_type') {
        [Console]::Error.WriteLine("NOTIFICATION[$($obj.notification_type)]: $frame")
        continue
    }
    if (($props -contains 'message') -and ([string]$obj.message -eq 'pong')) {
        [Console]::Error.WriteLine("PONG (ignored)")
        continue
    }
    if ($props -contains 'request_id') {
        if ([string]$obj.request_id -ne $reqId) {
            [Console]::Error.WriteLine("OTHER_RESPONSE (dropped): " + $frame.Substring(0, [Math]::Min(300, $frame.Length)))
            continue
        }
        $frame
        break
    }
    # no request_id echo → FIFO (single in-flight command on this connection)
    $frame
    break
}
try { $client.Close() } catch {}
